import java.util.*;

class Solution {
    public int maxProfit(int k, int[] prices) {
        if (prices.length == 0 || k == 0) return 0;
        final long NEG = Long.MIN_VALUE / 4;
        long[] hold = new long[k + 1], free = new long[k + 1];
        Arrays.fill(hold, NEG);
        for (int p : prices) {
            long[] nh = hold.clone(), nf = free.clone();
            for (int j = 1; j <= k; j++) {
                nh[j] = Math.max(hold[j], free[j - 1] - p);
                nf[j] = Math.max(free[j], hold[j] + p);
            }
            hold = nh;
            free = nf;
        }
        long best = 0;
        for (int j = 0; j <= k; j++) best = Math.max(best, free[j]);
        return (int) best;
    }
}

