class Solution {
    public int rob(int[] nums) {
        if (nums.length == 1) return nums[0];
        return Math.max(line(nums, 0, nums.length - 1), line(nums, 1, nums.length));
    }

    private int line(int[] nums, int lo, int hi) {
        int prev = 0, cur = 0;
        for (int i = lo; i < hi; i++) {
            int t = Math.max(cur, prev + nums[i]);
            prev = cur;
            cur = t;
        }
        return cur;
    }
}

