public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tk = new StringTokenizer("");

    static String next() throws IOException {
        while (!tk.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            tk = new StringTokenizer(line);
        }
        return tk.nextToken();
    }

    static TreeNode build(String[] a) {
        if (a.length == 0 || a[0].equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(a[0]));
        List<TreeNode> q = new ArrayList<>();
        q.add(root);
        int head = 0, i = 1;
        while (head < q.size() && i < a.length) {
            TreeNode node = q.get(head++);
            if (i < a.length) {
                if (!a[i].equals("null")) {
                    node.left = new TreeNode(Integer.parseInt(a[i]));
                    q.add(node.left);
                }
                i++;
            }
            if (i < a.length) {
                if (!a[i].equals("null")) {
                    node.right = new TreeNode(Integer.parseInt(a[i]));
                    q.add(node.right);
                }
                i++;
            }
        }
        return root;
    }

    static int[] dfs(TreeNode node) {
        if (node == null) return new int[]{0, 0};
        int[] l = dfs(node.left), r = dfs(node.right);
        int take = node.val + l[1] + r[1];
        int skip = Math.max(l[0], l[1]) + Math.max(r[0], r[1]);
        return new int[]{take, skip};
    }

    public static void main(String[] args) throws IOException {
        String t = next();
        if (t == null) return;
        int n = Integer.parseInt(t);
        String[] a = new String[n];
        for (int i = 0; i < n; i++) a[i] = next();
        int[] r = dfs(build(a));
        System.out.print(Math.max(r[0], r[1]));
    }
}

