class Solution {
    public int findTargetSumWays(int[] nums, int target) {
        int total = 0;
        for (int x : nums) total += x;
        if (total + target < 0 || ((total + target) & 1) != 0) return 0;
        int bag = (total + target) / 2;
        int[] dp = new int[bag + 1];
        dp[0] = 1;
        for (int x : nums) {
            for (int j = bag; j >= x; j--) dp[j] += dp[j - x];
        }
        return dp[bag];
    }
}

