class Solution {
    public int lastStoneWeightII(int[] stones) {
        int total = 0;
        for (int w : stones) total += w;
        int half = total / 2;
        int[] dp = new int[half + 1];
        for (int w : stones) {
            for (int j = half; j >= w; j--) dp[j] = Math.max(dp[j], dp[j - w] + w);
        }
        return total - 2 * dp[half];
    }
